def m2(x): return f"${x:,.2f}"
def stat(s): return {"official":OFFP,"law":LAWP,"pending":PENDP}[s]
MWNOADV='<div class="warn"><b>Not legal advice.</b> This page is general information built from official state sources, linked on every row. Trends Incoming is not a law firm or payroll provider, and nothing here is legal, tax or payroll advice for your situation. Local city and county rates, tipped, youth and industry rates can be different. Always confirm with your state labor department or a qualified professional before you act.</div>'
def mwrow(r,x):
    a,n,o,w,s,t,sl,su,note=x
    pg={"CA":MWCA,"WA":MWWA,"MI":MWMI,"NJ":MWNJ}.get(a)
    nm=f'<a href="{r}{pg}"><b>{n}</b></a>' if pg else f"<b>{n}</b>"
    new=m2(w) if w else "Pending"
    ch=f"+{m2(w-o)}" if w else "TBA"
    br="<br>" if note else ""
    return f'<tr><td>{nm}</td><td>{m2(o)}</td><td><b>{new}</b></td><td>{ch}</td><td>{stat(s)}</td><td>{esc(t)}</td><td class="src">{esc(note)}{br}<a href="{su}" rel="noopener" target="_blank">{esc(sl)}</a></td></tr>'
def mwtable(r):
    rows="".join(mwrow(r,x) for x in sorted(MWS,key=lambda x:-(x[3] or x[2])))
    return f'<div style="overflow-x:auto"><table><tr><th>State</th><th>Now (2026)</th><th>Jan 1, 2027</th><th>Raise</th><th>Status</th><th>Tipped cash wage 2027</th><th>Notes and official source</th></tr>{rows}<tr><td><a href="{r}{MWNY}"><b>New York</b></a></td><td>$17.00 / $16.00</td><td><b>$17.00 / $16.00</b></td><td>No raise</td><td>{OFFP}</td><td>$14.15 / $13.30 (service)</td><td class="src">NYC, Long Island, Westchester / rest of state<br><a href="{S_NY[1]}" rel="noopener" target="_blank">NY State DOL</a></td></tr><tr><td><b>Federal</b></td><td>$7.25</td><td><b>$7.25</b></td><td>No change</td><td>{OFFP}</td><td>$2.13</td><td class="src">Applies where state law is lower or missing<br><a href="{S_DOL[1]}" rel="noopener" target="_blank">U.S. DOL</a></td></tr></table></div>'
CALCD={a:{"n":n,"o":o,"w":w} for a,n,o,w,*_ in MWS}
CALCD.update({"NYC":{"n":"New York (NYC, Long Island, Westchester)","o":17.00,"w":17.00},"NYR":{"n":"New York (rest of state)","o":16.00,"w":16.00},"FED":{"n":"Federal minimum ($7.25 states)","o":7.25,"w":7.25}})
MWJS="""<script>(function(){var D=__D__;var s=document.getElementById("mws"),h=document.getElementById("mwh"),p=document.getElementById("mwp"),o=document.getElementById("mwr"),b=document.getElementById("mwgo");
function f(n){return n.toLocaleString("en-US",{style:"currency",currency:"USD"})}
function go(){var d=D[s.value],hr=parseFloat(h.value),own=parseFloat(p.value);if(!(hr>0&&hr<=100)){o.textContent="Type your hours per week (1 to 100).";return}
if(d.w===null){o.innerHTML="<b>"+d.n+"</b> hasn't posted its 2027 rate yet. At today's "+f(d.o)+" an hour, "+hr+" hours a week is "+f(d.o*hr)+" a week before taxes. We'll update this the day the state confirms.";return}
var base=(own>0)?own:d.o,nw=Math.max(base,d.w),wk=(nw-base)*hr;
var t="<b>"+d.n+"</b><br>2026 minimum: "+f(d.o)+" · Jan 1, 2027 minimum: <b>"+f(d.w)+"</b><br>";
if(own>0){t+=(own>=d.w?"You already earn at or above the new minimum, so the law doesn't require a raise for you.<br>":"Your pay must rise from "+f(own)+" to at least <b>"+f(d.w)+"</b> an hour.<br>")}
t+="Weekly pay at "+hr+" hours: "+f(base*hr)+" now, <b>"+f(nw*hr)+"</b> in 2027<br>Extra per week: <b>"+f(wk)+"</b> · per month: "+f(wk*52/12)+" · per year: <b>"+f(wk*52)+"</b><br><small>Gross pay before taxes and deductions. Ignores overtime, tips, local rates and special youth or tipped rates. Estimate only, not legal or payroll advice.</small>";o.innerHTML=t}
b.addEventListener("click",go);[h,p].forEach(function(x){x.addEventListener("keydown",function(e){if(e.key==="Enter"){e.preventDefault();go()}})});s.addEventListener("change",function(){if(h.value!=="")go()});
var q=new URLSearchParams(location.search).get("state");if(q&&D[q]){s.value=q}})();</script>""".replace("__D__",json.dumps(CALCD))
MSEL='style="font:inherit;padding:6px 10px;border:2px solid #16121f;border-radius:10px;margin:6px 0"'
def mwcalc(default="MI"):
    opts="".join(f'<option value="{k}"{" selected" if k==default else ""}>{esc(v["n"])}</option>' for k,v in sorted(CALCD.items(),key=lambda kv:kv[1]["n"]))
    w8=MSEL.replace("margin:6px 0","margin:6px 0;width:8em"); w16=MSEL.replace("margin:6px 0","margin:6px 0;width:16em")
    return f'''<div class="card" id="calculator" style="background:#effcff;margin:14px 0"><h2 style="margin-top:0">🧮 Paycheck calculator: what does the raise mean for me?</h2>
<p class="by">Runs in your browser. Nothing is sent anywhere.</p>
<form onsubmit="return false"><label for="mws"><b>State</b></label><br><select id="mws" {MSEL}>{opts}</select><br>
<label for="mwh"><b>Hours you work per week</b></label><br><input id="mwh" type="number" min="1" max="100" step="0.5" value="40" inputmode="decimal" {w8}><br>
<label for="mwp"><b>Your current hourly pay (optional)</b></label><br><input id="mwp" type="number" min="0" max="500" step="0.01" placeholder="blank = 2026 minimum" inputmode="decimal" {w16}><br>
<button type="button" id="mwgo" style="font:inherit;font-weight:800;border:2px solid #16121f;border-radius:10px;background:#ffd60a;padding:6px 14px;cursor:pointer;margin-top:8px">Show my 2027 pay</button>
<p id="mwr" aria-live="polite" style="font-size:1.02rem;margin-top:10px"></p></form></div>{MWJS}'''
