CSVROWS=["state,abbr,rate_2026,rate_2027_jan1,change,status,tipped_cash_wage_2027,source_url"]
for a,n,o,w,s,t,sl,su,note in MWS:
    CSVROWS.append(f'{n},{a},{o:.2f},{(f"{w:.2f}" if w else "pending")},{(f"{w-o:.2f}" if w else "")},{s},"{t}",{su}')
CSVROWS+=[f"New York (NYC/LI/Westchester),NY,17.00,17.00,0.00,official,14.15 (service),{S_NY[1]}",f"New York (rest of state),NY,16.00,16.00,0.00,official,13.30 (service),{S_NY[1]}",f"Federal,US,7.25,7.25,0.00,official,2.13,{S_DOL[1]}"]
os.makedirs(MW,exist_ok=True); open(MW+"minimum-wage-2027.csv","w").write("\n".join(CSVROWS)+"\n")
fullt="".join(f"<tr><td>{n}</td><td>+{m2(w-o)}</td><td><b>{m2((w-o)*2080)}</b></td></tr>" for a,n,o,w,*_ in sorted(SET,key=lambda x:-(x[3]-x[2])))
mbody=f'''<article><p class="by"><a href="../">💵 Money</a> › Minimum wage 2027</p><span class="pill">16 states raise pay Jan 1, 2027 · checked {FC19}</span>
<h1>Minimum Wage by State 2027: Every Raise on January 1</h1><p class="by">{BY} · Published Oct 19, 2026 · Last updated Oct 19, 2026</p>
<p><b>Short answer:</b> <b>16 states</b> raise their minimum wage on <b>January 1, 2027</b>. Washington tops the list at <b>$17.73</b>, and Michigan gets the biggest bump, <b>up $1.27 to $15.00</b>. Fifteen states have a confirmed number; Vermont is the one still pending. New York stays put, and the federal minimum is still $7.25. Every rate below links to the official state source. 🎉</p>
{MWNOADV}
{mwnav("../../",MW)}
<h2>📊 2027 minimum wage by state (January 1 raises)</h2><p>Sorted from highest to lowest. <b>Official</b> means the state labor agency announced it. <b>Set by law</b> means the number is written into state law. <b>Pending</b> means the state hasn't posted it yet. Tap a state name for its full guide.</p>
{mwtable("../../")}
<p class="src">Want the data? <a href="minimum-wage-2027.csv">Download the table as CSV</a>. Free to use with a link back.</p>
{mwcalc()}
<h2>💰 What the raise adds for a full-time worker</h2><p>The hourly raise times 2,080 hours (40 hours a week, 52 weeks), before taxes, for someone paid exactly the minimum:</p>
<table><tr><th>State</th><th>Hourly raise</th><th>Extra per year (full time)</th></tr>{fullt}</table>
<h2>🍽️ Tipped workers</h2><p>In many states the tipped cash wage moves with the minimum, and tips have to make up the rest. If cash wage plus tips falls short, the employer pays the difference. A few 2027 numbers straight from the states: Colorado <b>$12.69</b>, Arizona <b>$12.65</b>, Maine <b>$7.85</b>, New Jersey <b>$6.61</b>, Michigan <b>$6.30</b> (42% of the minimum), South Dakota <b>$6.15</b> and Ohio <b>$5.70</b>. California and Washington don't allow a tip credit at all, so tipped workers get the full minimum.</p>
<h2>⏳ The pending one: Vermont</h2><p>Vermont ties its minimum wage to inflation and raises it every January 1, but it hadn't posted the 2027 number when we checked on October 19, 2026 (today it's $14.42). Bloomberg Tax's calculation points to about <b>$14.91</b>; we'll swap in the official rate the day Vermont posts it.</p>
<p><b>Heads up on early reports:</b> some trackers still list Arizona as "expected." It's final. The Industrial Commission of Arizona posted its 2027 poster on September 25, 2026: <b>$15.65</b>.</p>
<h2>🗽 Not going up on January 1</h2><p><a href="../../{MWNY}">New York</a> skips its 2027 inflation raise because an off-ramp in state law was triggered, so it stays $17.00 downstate and $16.00 upstate. The federal $7.25 hasn't changed either. Several other states adjust on different dates, so check your state labor department if yours isn't listed.</p>
<div class="grid">
<div class="card"><span class="pill">$17.40</span><h3>🌴 California minimum wage 2027</h3><p>The new rate, the $72,384 exempt salary line, and local rates.</p><div class="links"><a class="in" href="../../{MWCA}">Read →</a></div></div>
<div class="card"><span class="pill">$17.73</span><h3>🌲 Washington minimum wage 2027</h3><p>Highest state rate in the country, plus the new overtime-exempt salaries.</p><div class="links"><a class="in" href="../../{MWWA}">Read →</a></div></div>
<div class="card"><span class="pill">+$1.27</span><h3>🚗 Michigan minimum wage 2027</h3><p>$15.00 and what it means for your paycheck, plus tipped and youth rates.</p><div class="links"><a class="in" href="../../{MWMI}">Read →</a></div></div>
<div class="card"><span class="pill">No raise</span><h3>🗽 New York minimum wage 2027</h3><p>Why it's staying at $17.00 and $16.00, and who still gets a raise.</p><div class="links"><a class="in" href="../../{MWNY}">Read →</a></div></div>
<div class="card"><span class="pill">$16.48</span><h3>🏖️ New Jersey minimum wage 2027</h3><p>Standard, small employer, seasonal, farm and tipped rates.</p><div class="links"><a class="in" href="../../{MWNJ}">Read →</a></div></div>
<div class="card"><span class="pill">For employers</span><h3>✅ Small business payroll checklist</h3><p>Ten things to do before your first 2027 payroll.</p><div class="links"><a class="in" href="../../{MWCK}">Open the checklist →</a></div></div></div>
{fhtml(MQ2)}{mwrel("../../")}{srcl(MWSRC)}</article>'''
MTITLE2="Minimum Wage by State 2027: Every Raise on January 1"
MDESC2="Every state minimum wage raise taking effect January 1, 2027, with official sources, tipped rates and a quick paycheck calculator. Updated as states confirm."
mwds={"@context":"https://schema.org","@type":"Dataset","name":"US state minimum wage rates on January 1, 2027","description":"Statewide minimum wage rates for 2026 and January 1, 2027 for the 16 states with a January 1, 2027 raise, plus New York and the federal minimum, with status (official, set by law, pending), tipped cash wages where published, and a link to each official state source.","url":B+"/"+MW,"creator":{"@type":"Organization","name":"The Trends Incoming team","url":B+"/about/"},"isBasedOn":[x[7] for x in MWS]+[S_NY[1]],"temporalCoverage":"2026/2027","spatialCoverage":"United States","isAccessibleForFree":True,"license":"https://creativecommons.org/licenses/by/4.0/","dateModified":PUB19,"variableMeasured":["Minimum hourly wage 2026","Minimum hourly wage January 1, 2027","Tipped cash wage 2027"],"distribution":[{"@type":"DataDownload","encodingFormat":"text/csv","contentUrl":B+"/"+MW+"minimum-wage-2027.csv"}]}
