def statepage(path,key,title,desc,h1,intro,facts,extra,faq,srcs,crumb):
    fr="".join(f"<tr><th>{esc(k)}</th><td>{v}</td></tr>" for k,v in facts)
    body=f'''<article><p class="by"><a href="../../">💵 Money</a> › <a href="../">Minimum wage 2027</a> › {esc(crumb)}</p><span class="pill">Checked {FC19}</span>
<h1>{esc(h1)}</h1><p class="by">{BY} · Published Oct 19, 2026 · Last updated Oct 19, 2026</p>
<p>{intro}</p>{MWNOADV}{mwnav("../../../",path)}<table>{fr}</table>{extra}{mwcalc(key)}{fhtml(faq)}{mwrel("../../../")}{srcl(srcs)}</article>'''
    page(path+"index.html",title,desc,body,ld=[art19(title,desc,path,srcs,h1),faqld(faq),crumbs(MWCR+[(crumb,path)])],article=False,cat="money")
statepage(MWCA,"CA","California Minimum Wage 2027: $17.40 and What It Means for Your Paycheck","California's minimum wage rises to $17.40 an hour on January 1, 2027. Weekly pay math, the $72,384 exempt salary threshold, local rates and a paycheck calculator.","California Minimum Wage 2027: $17.40 an Hour",
"California's statewide minimum wage goes from $16.90 to <b>$17.40 an hour</b> on <b>January 1, 2027</b>. That's 50 cents more, or about <b>$20 a week</b> and <b>$1,040 a year</b> for a full-time worker. The Department of Finance certified it on July 31, 2026, and it applies to every employer size.",
[("Jan 1, 2027 statewide rate",f"<b>$17.40</b> {OFFP}"),("2026 rate","$16.90"),("Raise","+$0.50 (about 3%)"),("Full-time weekly pay (40 hrs)","$676.00 now, <b>$696.00</b> in 2027"),("Overtime-exempt salary minimum","<b>$72,384</b> a year ($17.40 x 2 x 40 x 52)"),("Tip credit","Not allowed. Tips can't count toward the minimum."),("Learners","First 160 hours with no similar experience: at least 85% of the minimum")],
'<h2>🏙️ Check your city</h2><p>Lots of California cities and counties set their own higher minimum wage, and the higher local rate wins. Covered fast food workers and many health care workers also have their own higher state minimums. The state rate is the floor, not always your number.</p><h2>📋 For employers</h2><p>Post the updated statewide minimum wage order and your industry wage order where workers can see them, and show each worker\'s wage rate on the pay stub. See our <a href="../small-business-payroll-checklist/">payroll checklist</a>.</p>',
[("What is California's minimum wage in 2027?","$17.40 an hour from January 1, 2027, for all employers, unless a higher local or industry rate applies."),("How is California's minimum wage set?","It rises each year with the CPI-W inflation index, capped at 3.5% a year, and it can't go down. The Department of Finance certified the 2027 rate on July 31, 2026."),("What is the exempt salary threshold in California for 2027?","$72,384 a year, which is twice the state minimum wage for full-time work. Exempt employees also have to meet the duties tests."),("Can California employers count tips toward minimum wage?","No. California doesn't allow a tip credit.")],
[("CA DIR release 2026-66: $17.40 on Jan 1, 2027","https://www.dir.ca.gov/DIRNews/2026/2026-66.html"),S_CAGOV,S_CAFAQ],"California minimum wage 2027")
statepage(MWWA,"WA","Washington Minimum Wage 2027: $17.73, the Highest State Rate","Washington's minimum wage rises to $17.73 an hour on January 1, 2027, the highest state rate. Teen rate, overtime-exempt salaries and a paycheck calculator.","Washington Minimum Wage 2027: $17.73 an Hour",
"Washington keeps its crown: the minimum wage rises from $17.13 to <b>$17.73 an hour</b> on <b>January 1, 2027</b>, the highest statewide rate in the country. L&I announced the 3.5% raise on September 30, 2026. Full time, that's about <b>$24 more a week</b> and <b>$1,248 a year</b>.",
[("Jan 1, 2027 rate",f"<b>$17.73</b> {OFFP}"),("2026 rate","$17.13"),("Ages 14 and 15","$15.07 (85% of the minimum)"),("Full-time weekly pay (40 hrs)","$685.20 now, <b>$709.20</b> in 2027"),("Overtime-exempt salary, 51+ employees","<b>$1,773.00 a week</b> ($92,196.00 a year), 2.5x the minimum"),("Overtime-exempt salary, up to 50 employees","<b>$1,595.70 a week</b> ($82,976.40 a year), 2.25x the minimum"),("Tips","Can't be used toward the minimum wage")],
'<h2>🏙️ Local rates</h2><p>Some Washington cities set higher minimums than the state, so check your city\'s rate too. The higher one applies.</p><h2>📅 How it\'s set</h2><p>L&I adjusts the rate every year using the CPI-W inflation index, announces it on September 30 and makes it effective January 1.</p>',
[("What is Washington's minimum wage in 2027?","$17.73 an hour from January 1, 2027, per the Washington State Department of Labor & Industries."),("What is the minimum wage for 14 and 15 year olds in Washington in 2027?","$15.07 an hour, which is 85% of the adult minimum."),("What is the overtime-exempt salary in Washington for 2027?","For employers with 51 or more workers, $1,773.00 a week ($92,196.00 a year). For employers with up to 50 workers, $1,595.70 a week ($82,976.40 a year)."),("Can Washington employers use tips toward minimum wage?","No. Tips and service charges can't count toward the hourly minimum.")],
[("WA L&I: minimum wage","https://lni.wa.gov/workers-rights/wages/minimum-wage/"),S_WANEWS],"Washington minimum wage 2027")
statepage(MWMI,"MI","Michigan Minimum Wage 2027: $15.00 and What It Means for Your Paycheck","Michigan's minimum wage jumps $1.27 to $15.00 an hour on January 1, 2027, the biggest raise of any state. Tipped, youth and training rates plus a paycheck calculator.","Michigan Minimum Wage 2027: $15.00 an Hour",
"Michigan gets the biggest raise in the country: the minimum wage jumps from $13.73 to <b>$15.00 an hour</b> on <b>January 1, 2027</b>. That's <b>$1.27 more</b> an hour, about <b>$50.80 a week</b> and <b>$2,642 a year</b> for a full-time worker. It's written into state law, so it's locked in.",
[("Jan 1, 2027 rate",f"<b>$15.00</b> {LAWP}"),("2026 rate","$13.73"),("Raise","+$1.27 (about 9.2%)"),("Full-time weekly pay (40 hrs)","$549.20 now, <b>$600.00</b> in 2027"),("Tipped minimum cash wage","<b>$6.30</b> (42% of the minimum)"),("Workers under 18","<b>$12.75</b> (85% of the minimum)"),("Training wage","$4.25 for new hires under 20, first 90 days"),("Who's covered","Employers with 2 or more employees; workers 16 and older")],
'<h2>📈 Michigan\'s schedule</h2><table><tr><th>Effective</th><th>Minimum</th><th>Tipped cash wage</th><th>Under 18 (85%)</th></tr><tr><td>Feb 21, 2025</td><td>$12.48</td><td>$4.74</td><td>$10.61</td></tr><tr><td>Jan 1, 2026</td><td>$13.73</td><td>$5.49</td><td>$11.67</td></tr><tr><td><b>Jan 1, 2027</b></td><td><b>$15.00</b></td><td><b>$6.30</b></td><td><b>$12.75</b></td></tr></table><p>The tipped share keeps climbing: 44% of the minimum in 2028, 46% in 2029, 48% in 2030 and 50% from 2031. Tips plus cash wage must reach $15.00, or the employer makes up the difference.</p><p>Overtime rules don\'t change: time and a half after 40 hours in a workweek.</p>',
[("What is Michigan's minimum wage in 2027?","$15.00 an hour from January 1, 2027, under state law, per Michigan's Department of Labor and Economic Opportunity."),("What is the tipped minimum wage in Michigan in 2027?","$6.30 an hour, 42% of the minimum, as long as tips bring total pay to at least $15.00."),("What is the minimum wage for minors in Michigan in 2027?","Workers under 18 can be paid 85% of the minimum, which is $12.75 an hour."),("How much more will a full-time Michigan minimum wage worker make in 2027?","About $50.80 a week, or about $2,642 a year before taxes, at 40 hours a week.")],
[("Michigan LEO: minimum wage and overtime FAQ (2027 schedule)","https://www.michigan.gov/leo/bureaus-agencies/ber/wage-and-hour/frequently-asked-questions/wage-and-hour/minimum-wage-and-overtime-faq")],"Michigan minimum wage 2027")
statepage(MWNY,"NYC","New York Minimum Wage 2027: Why There's No Raise on January 1","New York's minimum wage stays $17.00 downstate and $16.00 upstate on January 1, 2027. Why the inflation raise was skipped, tipped rates and who still gets a raise.","New York Minimum Wage 2027: No Raise on January 1",
"Plot twist: New York's minimum wage <b>does not go up</b> on January 1, 2027. It stays <b>$17.00</b> in New York City, Long Island and Westchester and <b>$16.00</b> in the rest of the state. The state labor department says one of the inflation \"off-ramps\" in state law was triggered, so the yearly inflation bump is skipped. Home care aides are the big exception.",
[("NYC, Long Island, Westchester",f"<b>$17.00</b> (no change) {OFFP}"),("Rest of New York State","<b>$16.00</b> (no change)"),("Tipped service employees","$14.15 cash wage downstate; $13.30 upstate"),("Tipped food service workers","$11.35 cash wage downstate; $10.70 upstate"),("Home care aides","Rise to <b>$20.00</b> downstate and <b>$19.00</b> upstate")],
'<h2>🤔 Why no raise?</h2><p>New York law lets the minimum wage rise with inflation each year, but it also has conditions, called off-ramps, that can stop the automatic increase. The state says one was met for 2027. Home care aide rates still rise because they\'re adjusted for inflation but capped at $3.00 above the standard minimum. Governor Hochul has proposed changing the off-ramp rules; nothing has changed yet.</p>',
[("Is New York's minimum wage going up in 2027?","No. It stays $17.00 in New York City, Long Island and Westchester and $16.00 in the rest of the state on January 1, 2027, per the New York State Department of Labor."),("Why isn't New York's minimum wage increasing in 2027?","State law includes off-ramps that can block the automatic inflation increase, and the state says one of them was met for 2027."),("Who gets a raise in New York in 2027?","Home care aides: $20.00 an hour downstate and $19.00 upstate from January 1, 2027."),("What is the tipped minimum wage in New York for 2027?","For tipped food service workers, a $11.35 cash wage downstate and $10.70 upstate. For tipped service employees, $14.15 downstate and $13.30 upstate. Only hospitality employers can take a tip credit.")],
[S_NY],"New York minimum wage 2027")
statepage(MWNJ,"NJ","New Jersey Minimum Wage 2027: $16.48 for Most Workers","New Jersey's minimum wage rises to $16.48 an hour on January 1, 2027, with $16.25 for small and seasonal employers, $15 for farm workers and a $6.61 tipped cash wage.","New Jersey Minimum Wage 2027: $16.48 an Hour",
"New Jersey's minimum wage rises 56 cents to <b>$16.48 an hour</b> for most workers on <b>January 1, 2027</b>. Small and seasonal employers move to <b>$16.25</b>, and farm workers finally hit the <b>$15</b> benchmark. NJDOL announced the new rates on September 29, 2026.",
[("Most employees",f"<b>$16.48</b> (from $15.92) {OFFP}"),("Small employers (under 6 employees) and seasonal","<b>$16.25</b> (from $15.23)"),("Farm workers (hourly or piece rate)","<b>$15.00</b> (from $14.20)"),("Long-term care direct care staff","<b>$19.48</b>"),("Tipped cash wage","<b>$6.61</b> (from $6.05); max tip credit stays $9.87"),("Full-time weekly pay (40 hrs, most employees)","$636.80 now, <b>$659.20</b> in 2027")],
'<h2>📅 How it\'s set</h2><p>New Jersey\'s constitution ties the minimum wage to the Consumer Price Index, so it\'s adjusted every January 1. Small and seasonal employers finish their catch-up schedule in 2028, and farm employers in 2030; after that they rise with inflation too.</p>',
[("What is New Jersey's minimum wage in 2027?","$16.48 an hour for most employees from January 1, 2027, per the New Jersey Department of Labor and Workforce Development."),("What is the New Jersey minimum wage for small businesses in 2027?","$16.25 an hour for employers with fewer than six employees, and for seasonal employees."),("What is the tipped minimum wage in New Jersey in 2027?","A $6.61 cash wage, with a maximum tip credit of $9.87. If tips don't make up the difference, the employer pays it."),("What is the farm worker minimum wage in New Jersey in 2027?","$15.00 an hour for farm workers paid hourly or by piece rate.")],
[("NJDOL release: $16.48 on Jan 1, 2027 (Sep 29, 2026)","https://www.nj.gov/labor/lwdhome/press/2026/20260929_min_wage.shtml")],"New Jersey minimum wage 2027")
# ---- small business payroll checklist ----
CKL=[("Find every rate that applies","List each work location. Pay the highest rate that covers each worker: federal, state or local. Cities like Denver ($19.84 in 2027) and many California cities go well above the state rate."),
("Update pay rates for January 1","Set the new rates in payroll before your first 2027 pay period so hours worked from January 1 are paid at the new minimum."),
("Recheck tipped staff","If you take a tip credit, update the cash wage (for example Michigan $6.30, New Jersey $6.61, Colorado $12.69) and make sure tips plus cash wage reach the full minimum every workweek. California and Washington don't allow a tip credit."),
("Check youth, training and special rates","Some states have separate rates: Michigan under 18 ($12.75), Washington ages 14 and 15 ($15.07), Minnesota training wage ($9.68), New Jersey small and seasonal employers ($16.25)."),
("Recheck salaried exempt staff","Some states tie the overtime-exempt salary to the minimum wage. In 2027 it's $72,384 a year in California, and $92,196 (51+ employees) or $82,976.40 (up to 50) in Washington."),
("Fix overtime math","Overtime is time and a half of the regular rate. When the base rate goes up, overtime pay goes up too."),
("Put up the new posters","States issue new minimum wage posters when the rate changes. Arizona, Ohio, South Dakota and Montana have already posted their 2027 versions."),
("Update pay stubs and notices","Make sure pay stubs show the new rate where your state requires it (California does), and tell affected workers about the change."),
("Budget for payroll taxes","The raise also raises employer payroll taxes such as Social Security and Medicare. Build that into your 2027 budget, not just the hourly bump."),
("Watch for wage compression","When the floor moves up, workers just above it may now earn the same as new hires. Decide early whether you'll adjust those rates too.")]
CKQ=[("When do I have to start paying the 2027 minimum wage?","For the January 1 states, from January 1, 2027. Set the new rate in payroll before your first pay period of the year."),
("Which minimum wage do I pay if my city has a higher one?","Generally the highest rate that applies to the worker: federal, state or local."),
("Do I need a new minimum wage poster for 2027?","In most states that change their rate, yes. Download the free official poster from your state labor department."),
("Is this checklist legal advice?","No. It's a general starting point built from official sources. Confirm the rules for your business with your state labor department or a qualified professional.")]
CKSRC=[S_DOL,("CA DIR release 2026-66 ($72,384 exempt salary, posting and pay stub rules)","https://www.dir.ca.gov/DIRNews/2026/2026-66.html"),S_WANEWS,("Michigan LEO minimum wage FAQ","https://www.michigan.gov/leo/bureaus-agencies/ber/wage-and-hour/frequently-asked-questions/wage-and-hour/minimum-wage-and-overtime-faq"),("NJDOL release, Sep 29, 2026","https://www.nj.gov/labor/lwdhome/press/2026/20260929_min_wage.shtml"),("CDLE release (Denver $19.84)","https://cdle.colorado.gov/press-releases/press-release-colorado-minimum-wage-will-increase-to-1571/hour-in-2027"),("Ohio Commerce 2027 poster","https://dam.assets.ohio.gov/image/upload/com.ohio.gov/DICO/WageAndHour/2027_Minumum_Wage_Poster.pdf"),("Montana DLI 2027 poster","https://erd.dli.mt.gov/labor-standards/wage-and-hour-payment-act/2027-MINIMUM-WAGE-POSTER.pdf"),("Industrial Commission of Arizona posters","https://www.azica.gov/posters-employers-must-display"),("SD DLR 2027 poster","https://dlr.sd.gov/employment_laws/publications/min-wage-poster-2027-english.pdf"),("MN DLI release (training wage)","https://dli.mn.gov/news/minimum-wage-rate-adjusted-inflation-jan-1-2027")]
ckbody=f'''<article><p class="by"><a href="../../">💵 Money</a> › <a href="../">Minimum wage 2027</a> › Small business payroll checklist</p><span class="pill">For employers · checked {FC19}</span>
<h1>Small Business Payroll Checklist for the 2027 Minimum Wage Raises</h1><p class="by">{BY} · Published Oct 19, 2026 · Last updated Oct 19, 2026</p>
<p>Running payroll in one of the <b>16 states raising pay on January 1, 2027</b>? Here's a friendly ten-step checklist to get it right the first time. Grab a coffee, it's quicker than it looks. ☕</p>{MWNOADV}{mwnav("../../../",MWCK)}
<h2>✅ The checklist</h2><ol>{"".join(f"<li><b>{esc(a)}.</b> {esc(b)}</li>" for a,b in CKL)}</ol>
<h2>🧮 Quick cost math</h2><p>Extra wage cost per worker = new rate minus old rate, times hours. One full-time worker at the Michigan minimum costs about <b>$2,642 more a year</b> in wages ($1.27 x 2,080 hours), before payroll taxes. Use the <a href="../#calculator">paycheck calculator</a> for any state.</p>
<h2>⚠️ Special cases worth knowing</h2><ul><li><b>Ohio:</b> employers grossing under $419,000 pay at least the federal $7.25, per the state poster.</li><li><b>Montana:</b> some small businesses not covered by federal wage law with $110,000 or less in yearly sales may pay $4.00, per the state poster.</li><li><b>New Jersey:</b> small (under 6 employees) and seasonal employers pay $16.25; farm employers $15.00.</li><li><b>Vermont:</b> the 2027 rate isn't posted yet. Watch the state labor department.</li></ul>
<p>See every state's rate and official source on the <a href="../">2027 minimum wage by state</a> hub.</p>
{fhtml(CKQ)}{mwrel("../../../")}{srcl(CKSRC)}</article>'''
CKT="Small Business Payroll Checklist for the 2027 Minimum Wage Raises"
CKD="Ten steps to get payroll ready for the January 1, 2027 minimum wage raises: local rates, tipped and youth rates, exempt salaries, posters and budgeting. Not legal advice."
page(MWCK+"index.html",CKT,CKD,ckbody,ld=[art19(CKT,CKD,MWCK,CKSRC,"Minimum wage payroll compliance 2027"),{"@context":"https://schema.org","@type":"HowTo","name":"Get payroll ready for the 2027 minimum wage raises","step":[{"@type":"HowToStep","position":i+1,"name":a,"text":b} for i,(a,b) in enumerate(CKL)]},faqld(CKQ),crumbs(MWCR+[("Small business payroll checklist",MWCK)])],article=False,cat="money")
LM.update({B+"/"+p:PUB19 for p in (MW,MWCA,MWWA,MWMI,MWNY,MWNJ,MWCK)})
